export const LANGS = ['ru', 'en', 'ka'];
const KEY = 'crt-club:lang';
let current = (() => {
  try { const s = localStorage.getItem(KEY); if (LANGS.includes(s)) return s; } catch { /* no storage */ }
  const n = (navigator.language || 'en').slice(0, 2);
  return LANGS.includes(n) ? n : 'en';
})();
export const lang = () => current;
export function setLang(l) { if (!LANGS.includes(l)) return; current = l; try { localStorage.setItem(KEY, l); } catch { /* ignore */ } }

